// JavaScript's > would capture a constant: the reader refuses it.
// Spell it .gt(21) and the chain runs.
from(data).where((u) => u.age > 21)

// one chain, read as text and replayed against @jarenjs/linq
from(data)
  .where((u) => u.age.gt(21))
  .orderBy((u) => u.name)
  .select((u) => ({ id: u.id, name: u.name }))

// the document names $min; the value binds when it runs
from(data)
  .params({ min: 30 })
  .where((u, p) => u.age.ge(p.min))
  .select((u) => u.name)

